fn dark_of(x: f32, y: f32, form: &Form, color: &(dyn Fn(f32, f32, &Sample) -> Rgb + Sync)) -> Rgb {
    match form.sample(x, y) {
        Some(s) => {
            let mut s2 = s;
            s2.shade = Shade { turn: -0.3, direct: 0.0, cast: 1.0, bounce: 0.0, sky: 0.2, value: 0.0 };
            color(x, y, &s2)
        }
        None => hex("#303030"),
    }
}

